/** Routes tagged `sales · price lists`. */
export class SalesPriceListsResource extends Resource {
  /**
   * Cria uma tabela de preço.
   *
   * A tabela é o que responde "quanto custa": o cadastro do produto não guarda
   * preço, porque o mesmo SKU custa um valor no varejo e outro no atacado.
   *
   * A vigência é da TABELA, não do preço: é ela que entra ou sai de vigor. Marcar
   * `is_default` desmarca a tabela padrão anterior do mesmo escopo, em vez de
   * recusar a operação, porque foi isso que o operador quis dizer.
   *
   * `POST /v1/sales/price-lists`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createPriceList(body: S.CreatePriceListBody, options?: RequestOptions): Promise<S.SalesPriceListDto> {
    return this._http.request({ method: 'POST', path: `/v1/sales/price-lists`, body, options });
  }

  /**
   * Lista com keyset.
   *
   * Traz as tabelas do tenant. Por padrão só as ativas: a aposentada continua
   * existindo para os documentos que a citam, mas não é oferecida para
   * precificar nada novo.
   *
   * `GET /v1/sales/price-lists`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listPriceLists(query?: SalesPriceListsListPriceListsQuery, options?: RequestOptions): Promise<S.SalesPriceListPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/sales/price-lists`, query, options });
  }

  /**
   * Iterates every item of `listPriceLists`, following `next_page_token` page after page.
   *
   * `GET /v1/sales/price-lists`
   */
  listPriceListsAll(query?: SalesPriceListsListPriceListsQuery, options?: RequestOptions): Paginator<NonNullable<S.SalesPriceListPageDto["items"]>[number], S.SalesPriceListPageDto> {
    return new Paginator((page_token) => this.listPriceLists({ ...query, page_token } as SalesPriceListsListPriceListsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Lista com keyset.
   *
   * Cada linha vem com SKU e nome da variante no mesmo `JOIN`: a alternativa
   * seria a tela ler o cadastro item a item, que é onde a coluna aparece em
   * branco quando um id não casa.
   *
   * `GET /v1/sales/price-lists/{id}/prices`
   *
   * @param id ID da tabela (Snowflake)
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listPrices(id: string, query?: SalesPriceListsListPricesQuery, options?: RequestOptions): Promise<S.SalesPricePageDto> {
    return this._http.request({ method: 'GET', path: `/v1/sales/price-lists/${seg(id)}/prices`, query, options });
  }

  /**
   * Iterates every item of `listPrices`, following `next_page_token` page after page.
   *
   * `GET /v1/sales/price-lists/{id}/prices`
   */
  listPricesAll(id: string, query?: SalesPriceListsListPricesQuery, options?: RequestOptions): Paginator<NonNullable<S.SalesPricePageDto["items"]>[number], S.SalesPricePageDto> {
    return new Paginator((page_token) => this.listPrices(id, { ...query, page_token } as SalesPriceListsListPricesQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * `DELETE /v1/sales/price-lists/{id}/prices/{variant_id}`.
   *
   * Tira a variante da tabela. **Não afeta documento nenhum**: o preço que já foi
   * para uma linha é cópia congelada (invariante V1), e é isso que impede um
   * orçamento entregue ontem de mudar de valor hoje.
   *
   * `DELETE /v1/sales/price-lists/{id}/prices/{variant_id}`
   *
   * @param id ID da tabela (Snowflake)
   * @param variantId ID da variante/SKU (Snowflake)
   * @param options Per-call overrides.
   */
  removePrice(id: string, variantId: string, options?: RequestOptions): Promise<S.SalesPriceRemovedDto> {
    return this._http.request({ method: 'DELETE', path: `/v1/sales/price-lists/${seg(id)}/prices/${seg(variantId)}`, options });
  }

  /**
   * Define o preço.
   *
   * Idempotente: a segunda chamada com o mesmo par (tabela, variante) substitui
   * o valor em vez de criar uma segunda linha.
   *
   * Precifica o **SKU** (`variant_id`), nunca o modelo: é a variante que tem
   * saldo, é ela que é vendida, e duas variantes do mesmo modelo podem custar
   * valores diferentes.
   *
   * `PUT /v1/sales/price-lists/{id}/prices/{variant_id}`
   *
   * @param id ID da tabela (Snowflake)
   * @param variantId ID da variante/SKU (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setPrice(id: string, variantId: string, body: S.SetPriceBody, options?: RequestOptions): Promise<S.SalesPriceDto> {
    return this._http.request({ method: 'PUT', path: `/v1/sales/price-lists/${seg(id)}/prices/${seg(variantId)}`, body, options });
  }

  /**
   * `PATCH /v1/sales/price-lists/{id}`.
   *
   * Troca rótulo, vigência, padrão e atividade. Manda o registro inteiro: a
   * vigência ausente é gravada vazia. **Não muda código nem moeda**: os
   * dois são identidade da tabela, e trocá-los reinterpretaria em outra unidade
   * todo preço já gravado nela. Quem precisa de outra moeda cria outra tabela.
   *
   * `PATCH /v1/sales/price-lists/{id}`
   *
   * @param id ID da tabela (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updatePriceList(id: string, body: S.UpdatePriceListBody, options?: RequestOptions): Promise<S.SalesPriceListDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/sales/price-lists/${seg(id)}`, body, options });
  }
}

/** Routes tagged `sales · returns`. */
export class SalesReturnsResource extends Resource {
  /**
   * Uma devolução.
   *
   * Inclui as linhas devolvidas e a situação da devolução.
   *
   * `GET /v1/sales/returns/{id}`
   *
   * @param id ID da devolução (Snowflake)
   * @param options Per-call overrides.
   */
  getReturn(id: string, options?: RequestOptions): Promise<S.SalesOrderReturnDto> {
    return this._http.request({ method: 'GET', path: `/v1/sales/returns/${seg(id)}`, options });
  }

  /**
   * Emite a NF-e de devolução.
   *
   * `finNFe = 4`, referenciando a nota da venda, com o CFOP de devolução de
   * cada linha. **Idempotente**: repetir devolve a mesma nota.
   *
   * `POST /v1/sales/returns/{id}/fiscal-documents`
   *
   * @param id ID da devolução (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  issueReturnDocument(id: string, body: S.IssueReturnDocumentBody, options?: RequestOptions): Promise<S.SalesOrderReturnDocumentListDto> {
    return this._http.request({ method: 'POST', path: `/v1/sales/returns/${seg(id)}/fiscal-documents`, body, options });
  }

  /**
   * A nota da devolução.
   *
   * A nota fiscal emitida para a devolução, com a situação dela.
   *
   * `GET /v1/sales/returns/{id}/fiscal-documents`
   *
   * @param id ID da devolução (Snowflake)
   * @param options Per-call overrides.
   */
  listReturnDocuments(id: string, options?: RequestOptions): Promise<S.SalesOrderReturnDocumentListDto> {
    return this._http.request({ method: 'GET', path: `/v1/sales/returns/${seg(id)}/fiscal-documents`, options });
  }

  /**
   * As devoluções da venda, em ordem.
   *
   * Cada devolução traz as linhas devolvidas e o valor.
   *
   * `GET /v1/sales/orders/{id}/returns`
   *
   * @param id ID da venda (Snowflake)
   * @param options Per-call overrides.
   */
  listReturns(id: string, options?: RequestOptions): Promise<S.SalesOrderReturnListDto> {
    return this._http.request({ method: 'GET', path: `/v1/sales/orders/${seg(id)}/returns`, options });
  }

  /**
   * Registra uma devolução.
   *
   * Só a venda faturada aceita devolução. O crédito de cada linha é a parte
   * proporcional do total efetivo, e a última devolução da linha fecha no
   * resto, para a soma nunca passar do que foi cobrado.
   *
   * `POST /v1/sales/orders/{id}/returns`
   *
   * @param id ID da venda (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `Idempotency-Key`.
   */
  registerReturn(id: string, body: S.RegisterReturnBody, options?: RequestOptions & { headers?: { "Idempotency-Key"?: string } }): Promise<S.SalesOrderReturnDto> {
    return this._http.request({ method: 'POST', path: `/v1/sales/orders/${seg(id)}/returns`, body, options });
  }
}

