/** Routes tagged `sales · team`. */
export class SalesTeamResource extends Resource {
  /**
   * Põe uma pessoa na equipe.
   *
   * Só quem está ativo na equipe entra como vendedor ou executante de um pedido.
   *
   * `POST /v1/sales/salespeople`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  addSalesperson(body: S.AddSalespersonBody, options?: RequestOptions): Promise<S.SalespersonDto> {
    return this._http.request({ method: 'POST', path: `/v1/sales/salespeople`, body, options });
  }

  /**
   * Cria um cargo comercial.
   *
   * O nome é único na organização. O cargo pode apontar para um cargo do RH, só
   * como referência.
   *
   * `POST /v1/sales/roles`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createRole(body: S.SalesRoleBody, options?: RequestOptions): Promise<S.SalesRoleDto> {
    return this._http.request({ method: 'POST', path: `/v1/sales/roles`, body, options });
  }

  /**
   * Apaga o cargo sem vendedor ativo.
   *
   * Os inativos ficam sem cargo e as regras de comissão do cargo somem com ele.
   * Com vendedor ativo no cargo responde `412`.
   *
   * `DELETE /v1/sales/roles/{id}`
   *
   * @param id ID do cargo (Snowflake)
   * @param options Per-call overrides.
   */
  deleteRole(id: string, options?: RequestOptions): Promise<void> {
    return this._http.request({ method: 'DELETE', path: `/v1/sales/roles/${seg(id)}`, responseType: 'void', options });
  }

  /**
   * Quem vendeu e quem executa.
   *
   * Os participantes do documento por papel (`seller` e `executor`), que a
   * comissão por papel usa na confirmação.
   *
   * `GET /v1/sales/orders/{id}/participants`
   *
   * @param id ID do documento (Snowflake)
   * @param options Per-call overrides.
   */
  getParticipants(id: string, options?: RequestOptions): Promise<S.SalesOrderParticipantsDto> {
    return this._http.request({ method: 'GET', path: `/v1/sales/orders/${seg(id)}/participants`, options });
  }

  /**
   * Os cargos comerciais.
   *
   * Cada cargo vem com quantos vendedores ativos ele tem. O cargo é o nível do
   * meio da meta e da comissão, entre a empresa e a pessoa.
   *
   * `GET /v1/sales/roles`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listRoles(query?: SalesTeamListRolesQuery, options?: RequestOptions): Promise<S.SalesRolePageDto> {
    return this._http.request({ method: 'GET', path: `/v1/sales/roles`, query, options });
  }

  /**
   * Iterates every item of `listRoles`, following `next_page_token` page after page.
   *
   * `GET /v1/sales/roles`
   */
  listRolesAll(query?: SalesTeamListRolesQuery, options?: RequestOptions): Paginator<NonNullable<S.SalesRolePageDto["items"]>[number], S.SalesRolePageDto> {
    return new Paginator((page_token) => this.listRoles({ ...query, page_token } as SalesTeamListRolesQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * A equipe comercial.
   *
   * Lista quem vende e quem executa, com cargo e situação. O nome da pessoa vem
   * do `iam` na tela.
   *
   * `GET /v1/sales/salespeople`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listSalespeople(query?: SalesTeamListSalespeopleQuery, options?: RequestOptions): Promise<S.SalespersonPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/sales/salespeople`, query, options });
  }

  /**
   * Iterates every item of `listSalespeople`, following `next_page_token` page after page.
   *
   * `GET /v1/sales/salespeople`
   */
  listSalespeopleAll(query?: SalesTeamListSalespeopleQuery, options?: RequestOptions): Paginator<NonNullable<S.SalespersonPageDto["items"]>[number], S.SalespersonPageDto> {
    return new Paginator((page_token) => this.listSalespeople({ ...query, page_token } as SalesTeamListSalespeopleQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Troca os participantes de um papel.
   *
   * Só entra quem está ativo na equipe. A comissão já lançada só muda pelo
   * recalcular.
   *
   * `PUT /v1/sales/orders/{id}/participants/{role}`
   *
   * @param id ID do documento (Snowflake)
   * @param role seller | executor
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setParticipants(id: string, role: string, body: S.SetParticipantsBody, options?: RequestOptions): Promise<S.SalesOrderParticipantsDto> {
    return this._http.request({ method: 'PUT', path: `/v1/sales/orders/${seg(id)}/participants/${seg(role)}`, body, options });
  }

  /**
   * Renomeia o cargo.
   *
   * Também troca a referência ao cargo do RH quando `hr_job_id` vem no corpo;
   * ausente, a referência fica. Metas e regras de comissão do cargo seguem com
   * ele.
   *
   * `PATCH /v1/sales/roles/{id}`
   *
   * @param id ID do cargo (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateRole(id: string, body: S.SalesRoleBody, options?: RequestOptions): Promise<S.SalesRoleDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/sales/roles/${seg(id)}`, body, options });
  }

  /**
   * Troca o cargo ou desliga.
   *
   * Desligar não tira a pessoa dos pedidos em que já está, nem da comissão já
   * lançada.
   *
   * `PATCH /v1/sales/salespeople/{member_id}`
   *
   * @param memberId Membro (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateSalesperson(memberId: string, body: S.UpdateSalespersonBody, options?: RequestOptions): Promise<S.SalespersonDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/sales/salespeople/${seg(memberId)}`, body, options });
  }
}

